"use client";

import React, { useState, useRef } from "react";
import { motion, animate, useMotionValue, useReducedMotion } from "motion/react";
import { ShoppingBag } from "lucide-react";
import { cn } from "@/lib/utils";

export interface AddToBasketProps
  extends React.HTMLAttributes<HTMLDivElement> {
  productName?: string;
  price?: string;
  glyph?: string;
}

export function AddToBasket({
  productName = "Campus 00s",
  price = "£128",
  glyph = "👟",
  className,
  ...props
}: AddToBasketProps) {
  const [basketCount, setBasketCount] = useState(0);
  const [isFlying, setIsFlying] = useState(false);

  const productRef = useRef<HTMLDivElement>(null);
  const basketRef = useRef<HTMLDivElement>(null);
  const ringRef = useRef<HTMLDivElement>(null);

  const shouldReduceMotion = useReducedMotion();
  const productX = useMotionValue(0);
  const productY = useMotionValue(0);
  const productScale = useMotionValue(1);
  const productOpacity = useMotionValue(1);

  const basketX = useMotionValue(0);
  const basketY = useMotionValue(0);
  const ringScale = useMotionValue(1);
  const ringOpacity = useMotionValue(0);

  const handleAdd = async () => {
    if (isFlying || !productRef.current || !basketRef.current) return;
    setIsFlying(true);

    if (shouldReduceMotion) {
      setBasketCount((c) => c + 1);
      setIsFlying(false);
      return;
    }

    const from = productRef.current.getBoundingClientRect();
    const to = basketRef.current.getBoundingClientRect();
    const dx = to.left + to.width / 2 - (from.left + from.width / 2);
    const dy = to.top + to.height / 2 - (from.top + from.height / 2);

    // Fly product in parabolic arc
    await Promise.all([
      animate(productX, dx, { duration: 0.45, ease: [0.74, 0.18, 0.93, 0.69] }),
      animate(productY, dy, { duration: 0.45, ease: "easeIn" }),
      animate(productScale, 0.35, { duration: 0.45 }),
      animate(productOpacity, [1, 1, 0], { duration: 0.45, times: [0, 0.8, 1] }),
    ]);

    setBasketCount((c) => c + 1);

    // Basket impact reaction
    animate(
      basketRef.current,
      { rotate: [-10, 10, -5, 5, 0], scale: [1, 1.2, 0.95, 1] },
      { duration: 0.45, ease: "easeOut" }
    );

    // Basket ripple ring
    if (ringRef.current) {
      animate(ringRef.current, { scale: [1, 2.4], opacity: [0.8, 0] }, { duration: 0.5, ease: "easeOut" });
    }

    // Reset product position and bounce fresh product back in
    productX.set(0);
    productY.set(0);
    productScale.set(0.6);
    productOpacity.set(0);

    await animate(
      productRef.current,
      { scale: [0.6, 1.08, 1], opacity: 1 },
      { duration: 0.35, ease: "backOut" }
    );

    productScale.set(1);
    productOpacity.set(1);
    setIsFlying(false);
  };

  return (
    <div
      data-slot="add-to-basket"
      className={cn(
        "relative flex min-h-[460px] w-full max-w-lg flex-col items-center justify-center p-8 select-none font-mono",
        className
      )}
      {...props}
    >
      {/* Basket in Top Right Corner */}
      <div className="absolute top-6 right-6 flex items-center gap-2">
        <motion.div
          ref={basketRef}
          style={{ x: basketX, y: basketY }}
          className="relative flex h-14 w-14 items-center justify-center rounded-2xl border border-neutral-200 bg-white dark:border-neutral-800 dark:bg-neutral-900 shadow-lg text-emerald-600 dark:text-emerald-400"
        >
          <motion.div
            ref={ringRef}
            style={{ scale: ringScale, opacity: ringOpacity }}
            className="pointer-events-none absolute -inset-1 rounded-2xl border-2 border-emerald-500"
          />
          <ShoppingBag className="h-6 w-6" />
          {basketCount > 0 ? (
            <span className="absolute -top-1.5 -right-1.5 flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500 text-[10px] font-bold text-white shadow-md">
              {basketCount}
            </span>
          ) : null}
        </motion.div>
      </div>

      {/* Center Product Card */}
      <div className="flex flex-col items-center gap-5 mt-8">
        <motion.div
          ref={productRef}
          style={{
            x: productX,
            y: productY,
            scale: productScale,
            opacity: productOpacity,
          }}
          className="flex h-40 w-40 items-center justify-center rounded-3xl border border-neutral-200 bg-neutral-50 dark:border-neutral-800 dark:bg-neutral-900 shadow-xl"
        >
          <span className="text-6xl select-none">{glyph}</span>
        </motion.div>

        <div className="flex items-baseline gap-3 text-sm">
          <span className="font-bold text-neutral-900 dark:text-neutral-100">{productName}</span>
          <span className="font-semibold text-emerald-600 dark:text-emerald-400">{price}</span>
        </div>

        <motion.button
          type="button"
          disabled={isFlying}
          onClick={handleAdd}
          whileHover={{ scale: 1.04 }}
          whileTap={{ scale: 0.96 }}
          className="rounded-full bg-neutral-900 px-7 py-3 text-xs font-bold uppercase tracking-widest text-white shadow-lg transition-colors hover:bg-neutral-800 disabled:opacity-50 dark:bg-neutral-100 dark:text-neutral-900 dark:hover:bg-neutral-200 cursor-pointer"
        >
          Add to basket
        </motion.button>
      </div>
    </div>
  );
}
